import express from 'express';

const app = express();
app.use(express.json());

// 1. Erro com status: a rota marca o que o cliente deve receber.
class AppError extends Error {
  constructor(status, mensagem) {
    super(mensagem);
    this.status = status;
  }
}

const livros = [{ id: 1, titulo: 'Dom Casmurro' }];

// 2. Validação falhou → 422 (dado até chegou, mas com formato inválido).
app.post('/api/livros', (req, res, next) => {
  if (!req.body?.titulo) {
    return next(new AppError(422, 'campo titulo é obrigatório'));
  }
  res.status(201).json({ criado: true });
});

// 3. Item que não existe → 404.
app.get('/api/livros/:id', (req, res, next) => {
  const livro = livros.find((l) => l.id === Number(req.params.id));
  if (!livro) {
    return next(new AppError(404, 'livro não encontrado'));
  }
  res.json(livro);
});

// 4. Rota que QUEBRA de propósito: erro sem status → 500.
app.get('/api/relatorio', () => {
  throw new Error('o banco caiu de novo');
});

// 5. O extintor central: uma única esteira para todos os erros.
app.use((erro, req, res, next) => {
  console.error('erro na API:', erro); // log completo SÓ no servidor
  const status = erro.status >= 400 && erro.status < 500 ? erro.status : 500;
  const mensagem = status < 500 ? erro.message : 'erro interno do servidor';
  // 6. Resposta segura: formato padrão, sem stack trace, sem detalhes internos.
  res.status(status).json({ erro: { mensagem } });
});

app.listen(3000);
